with runtime_clock as ( select format_datetime(now() - interval '24' hour, 'YYYYMMdd') as dt_24h, format_datetime(now() - interval '2' hour, 'YYYYMMdd') as dt_2h, format_datetime(now() - interval '24' hour, 'HH') as hour_24h, format_datetime(now() - interval '3' hour, 'HH') as hour_3h, format_datetime(now() - interval '2' hour, 'HH') as hour_2h ) , biz_qici_calendar as ( select * from ( values ('20260716期', date '2026-07-14', date '2026-07-19'), ('20260722期', date '2026-07-20', date '2026-07-25'), ('20260728期', date '2026-07-26', date '2026-07-31'), ('20260803期', date '2026-08-01', date '2026-08-06'), ('20260808期', date '2026-08-07', date '2026-08-12'),
('20260815期', date '2026-08-13', date '2026-08-18') ) as t(qici, start_date, end_date) ), market_employee_dim as ( select account_id, employee_email_name, email_prefix, employee_name, is_on_job, job_status, last_resign_date from finance_dw.dim_finance_employee_df t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '24' HOUR, 'YYYYMMdd')) and t.first_level_department_name = 'H业务线' and t.second_level_department_name = '市场部' and t.third_level_department_name = '市场顾问部' ), private_stage_latest as ( select user_number, sale_flow_stage_sequence, is_abnormal_stage, case when sale_flow_stage_sequence = '450' then '深沟' when sale_flow_stage_sequence = '470' then '已双沟' else '其他' end as jieduan from ( select p.user_number, p.sale_flow_stage_sequence, case when p.sale_flow_stage_sequence in ('50', '150', '1000') then 1 else 0 end as is_abnormal_stage, row_number() over ( partition by p.user_number order by p.private_sea_update_time desc ) as rn from service_dw.dwd_crm_assign_private_detail_hf p  where p.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and p.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) and p.assign_employee_first_level_department_name = 'H业务线' and p.assign_employee_second_level_department_name = '市场部' and p.assign_employee_third_level_department_name = '市场顾问部' ) t where rn = 1 ), lead_stats as ( select lead_id, date_diff( 'hour', cast(section_assign_time as timestamp), cast(section_assign_first_call_connected_time as timestamp) ) as first_call_connected_time_diff_hour from service_dw.dm_crm_lead_stats_detail_hf t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and t.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) and t.mapping_first_level_department_name = 'H业务线' and t.mapping_second_level_department_name in ('精品班学部', '菁英班学部', '市场部', '本地化大班学部') ), abnormal_label as ( select user_number, abnormal_traffic from service_dw.app_user_attribute_label_gaia_wide_df t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '24' HOUR, 'YYYYMMdd')) and t.type = 'key' ), double_table as ( select assign_employee_email_name, user_id, send_double_table from ( select t.assign_employee_email_name, t.user_id, t.send_double_table, row_number() over ( partition by t.user_id, t.assign_employee_email_name order by t.trace_update_time desc ) as rn from service_dw.app_h_crm_lead_task_process_info_detail_hf t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and t.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) and t.virtual_department_name_2 = 'H业务线' and t.virtual_department_name_3 = '市场部' ) x where rn = 1 ), call_c as ( select sub.user_number, sub.lead_id, sub.section_assign_employee_email_prefix, max(case when sub.call_duration > 300 then 1 else 0 end) as is_long_call, sum(sub.call_duration) as call_duration_1, sum(case when sub.call_status in ('1', '0') then 1 else 0 end) as zong_call_ci_1, sum(case when sub.call_status = '1' then 1 else 0 end) as call_status_1 from ( select distinct wf.user_number, wf.lead_id, wf.section_assign_employee_email_prefix, wf.call_duration, wf.call_status, wf.call_time, wf.call_type_name, wf.data_source, wf.msg_type_name from service_dw.app_h_crm_lead_employee_workload_detail_hf wf  where wf.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and wf.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) ) sub group by sub.user_number, sub.lead_id, sub.section_assign_employee_email_prefix ), f_call0 as ( select a.user_id, b.employee_email_name as assign_employee_email_name, case when sum(if(a.first_call_status = 3, 1, 0)) > 0 then 1 else 0 end as call_answer_lead_count from ( select user_id, first_call_status, account_id from gaotu_crm_offline_statistics.app_mcrm_first_call_task_hf t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and t.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) and t.start_time > '2026-01-01' and t.is_del = 0 ) a inner join ( select account_id, employee_email_name from market_employee_dim ) b on a.account_id = b.account_id group by a.user_id, b.employee_email_name ), d_ap as ( select user_latest.user_number, case when user_latest.event_timestamp >= now() - interval '7' day and user_latest.appliction_name in ('PC客户端', 'APP', 'PC') then 1 else 0 end as is_app_denglu_d from ( select ul.user_number, ul.appliction_name, try(date_parse(ul.last_event_time, '%Y-%m-%d %H:%i:%s:%f')) as event_timestamp from ( select t.*, row_number() over ( partition by t.user_number order by try(date_parse(t.last_event_time, '%Y-%m-%d %H:%i:%s:%f')) desc ) as rn from dw.dim_cstm_active_user_c_appliction_mb_df t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '24' HOUR, 'YYYYMMdd')) and t.product_name in ('高途', '规划精品') ) ul where rn = 1 ) user_latest ), h_ap as ( select t.user_number, max(case when t.application_name in ('PC客户端', 'APP', 'PC') then 1 else 0 end) as is_app_denglu_h from dw.dws_user_active_user_c_appliction_hf t  where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and t.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) and t.product_name in ('高途', '规划精品') group by t.user_number ), denglu_app as ( select d_ap.user_number, case when coalesce(h_ap.is_app_denglu_h, 0) = 1 or coalesce(d_ap.is_app_denglu_d, 0) = 1 then 1 else 0 end as is_app_denglu from d_ap left join h_ap on d_ap.user_number = h_ap.user_number ), lead_raw0 as ( select coalesce(lead_cal.qici, concat( date_format( date_trunc( 'week', date_parse(replace(concat(f.group_period_year, f.group_period_term), '期', ''), '%Y%m%d') - interval '1' day ) + interval '4' day, '%Y%m%d' ), '期' )) as pn, f.lead_id as lid, f.user_id as uid, f.employee_email_name as een, f.employee_email_prefix as eep, f.rule_name as rn, f.virtual_third_department_name as d1, f.virtual_fourth_department_name as rd, f.virtual_leader_email_name as rj, f.virtual_direct_leader_email_name as rx, f.flow_pool_name as fp, f.sku_id_name as sku, f.ad_account_name as aa, f.source_manager_name as sm, f.channel_name_1 as c1, f.channel_name_2 as c2, f.channel_name_3 as c3, f.put_plan_name as pp, cast(f.flow_original_order_activity_price as varchar) as foap, cast(f.flow_orders_income_amount as varchar) as foia, cast(f.flow_order_price as varchar) as fop, f.channel_provider_name as cpn, f.channel_second_provider_name as cspn, f.page_id_name as pid, f.source_put_plan_name as spp, f.get_customer_way_name as gcw, f.first_department_name as fd, f.second_department_name as sd, f.third_department_name as td, f.virtual_second_department_name as v2, f.virtual_fourth_department_name as v4, f.virtual_fifth_department_name as v5, f.lead_purchase_intention_name as lpi, f.trace_type_name as tt, f.lead_purchase_intention_level1_category_name as lp1, f.lead_purchase_intention_level2_category_name as lp2, f.lead_create_time as lct, f.section_assign_time as sat, f.first_call_time as fct, f.deep_communicate_method as dcm, f.intention_level as itl, coalesce(f.lead_count, 0) as lead_count, coalesce(f.valid_lead_count, 0) as valid_lead_count, coalesce(f.conversion_lead_count, 0) as conversion_lead_count, coalesce(f.subject_count, 0) as subject_count, coalesce(f.same_lead_period_subject_count, 0) as slps_count, coalesce(f.lb_subject_count, 0) as lb_subject_count, coalesce(f.same_lead_period_lb_subject_count, 0) as slplb_count, coalesce(f.order_count, 0) as order_count, coalesce(f.income_amount, 0) as income_amount, coalesce(f.in_pay_period_refund_amount, 0) as in_pay_period_refund_amount, coalesce(f.non_pay_period_refund_amount, 0) as non_pay_period_refund_amount, coalesce(f.same_lead_period_conversion_lead_count, 0) as slpc_count, coalesce(f.same_lead_period_income_amount, 0) as slpi_amount, coalesce(f.same_lead_period_refund_amount, 0) as slpr_amount, coalesce(f.friend_lead_count, 0) as friend_lead_count, coalesce(f.lead_cost, 0) as lead_cost, coalesce(f.target_lead_cost_per_lead, 0) as target_lead_cost_per_lead, coalesce(f.target_same_department_net_conversion_per_lead, 0) as target_same_department_net_conversion_per_lead from bdg_ba.dm_crm_lead_cost_gmv_communication_learn_full_link_df f  left join biz_qici_calendar lead_cal on cast(date_parse(replace(concat(f.group_period_year, f.group_period_term), '期', ''), '%Y%m%d') as date) between lead_cal.start_date and lead_cal.end_date where f.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and f.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '3' HOUR, 'HH')) and f.section_assign_employee_first_level_department_name = 'H业务线' and f.section_assign_employee_second_level_department_name = '市场部' and f.section_assign_employee_third_level_department_name = '市场顾问部' and f.period_mapping_first_level_department_name = 'H业务线' and f.period_mapping_second_level_department_name IN ('精品班学部', '菁英班学部', '市场部', '本地化大班学部') ), lead_raw as ( select a.*, a.pn not like '%多学科拓展%' as nm, a.td = '直播部' as ld, a.td in ('直播部', '新媒体内容运营部', '市场一组', '私域运营部') as l4, a.td in ('直播部', '新媒体内容运营部', '市场一组') as l3, a.fp like '%自然流%' as nf, a.sm in ('孙晗01','方俊结01','刘亦鹏02','何木玲','杨梓月','张可意03','任颖迪','曹蕊07','曲默晗') as km, a.sm in ('包青青','蔡瑞涵','李文迁','李佳馨44','孙昊17','王洁雅01','王硕北','朱文','贾铭锐','李壮壮04','陈晓菁04','赵艺雅') as smg, a.sm in ('耿文超','晋翠翠','赵语诗','王慧敏13','于新茹','梁超01','刘晓20','王玉120','吕佳乐01') as cmg, a.c1 = '信息流' as ifl, a.c1 = '信息流' and a.c2 = 'B站' as ib, a.c1 = '信息流' and a.c2 = 'B站' and a.td not like '%投放%' as ibn, a.td in ('品牌效能部', 'KOC孵化部') and a.c2 in ('抖音', '视频号', '快手', 'KOL') as ik, regexp_like(a.fp, '孟帝|孟老师|中考数学冲刺|8升9数学|孟亚飞讲数学|中考冲刺|中考满分冲刺|押题王孟亚飞|中考数学大通关|中考数学规划|亚飞数学|孟帝数学|亚飞秒解思维') as yp from lead_raw0 a where a.pn >= ${qici:1} and a.pn < ${qici:2} ), lead_channel_dim AS (
