lead_base_all as ( select pn as qici, channel, case when rn like '%高一%' then '高一' when rn like '%高二%' then '高二' when rn like '%高三%' then '高三' when rn like '%初一%' then '初一' when rn like '%初二%' then '初二' when rn like '%初三%' then '初三' else lp2 end as grade, lid as lead_id, uid as user_id, een as employee_email_name, eep as employee_email_prefix, rn as rule_name, d1 as depart_1, rd as raw_department, rj as raw_jingli, rx as raw_zhuguan, sat as section_assign_time, fct as first_call_time, dcm as deep_communicate_method, itl as intention_level, lead_count, valid_lead_count, conversion_lead_count, subject_count, slps_count as same_lead_period_subject_count, lb_subject_count, slplb_count as same_lead_period_lb_subject_count, order_count, income_amount, in_pay_period_refund_amount, non_pay_period_refund_amount, slpc_count as same_lead_period_conversion_lead_count, slpi_amount as same_lead_period_income_amount, slpr_amount as same_lead_period_refund_amount, friend_lead_count, lead_cost, target_lead_cost_per_lead, target_same_department_net_conversion_per_lead from lead_raw_mapped ), lead_base as ( select b.*, case when b.qici is not null and b.lead_id is not null and b.employee_email_name is not null and b.employee_email_prefix is not null then first_value(b.raw_department) over ( partition by b.qici, b.lead_id, b.employee_email_name, b.employee_email_prefix order by case when coalesce(b.lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.valid_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.conversion_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.order_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.income_amount, 0) <> 0 then 0 else 1 end, case when b.raw_department is not null and trim(cast(b.raw_department as varchar)) <> '' then 0 else 1 end, case when b.raw_jingli is not null and trim(cast(b.raw_jingli as varchar)) <> '' then 0 else 1 end, case when b.raw_zhuguan is not null and trim(cast(b.raw_zhuguan as varchar)) <> '' then 0 else 1 end, coalesce(cast(b.raw_department as varchar), ''), coalesce(cast(b.raw_jingli as varchar), ''), coalesce(cast(b.raw_zhuguan as varchar), ''), coalesce(cast(b.channel as varchar), ''), coalesce(cast(b.grade as varchar), '') ) end as department, case when b.qici is not null and b.lead_id is not null and b.employee_email_name is not null and b.employee_email_prefix is not null then first_value(b.raw_jingli) over ( partition by b.qici, b.lead_id, b.employee_email_name, b.employee_email_prefix order by case when coalesce(b.lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.valid_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.conversion_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.order_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.income_amount, 0) <> 0 then 0 else 1 end, case when b.raw_department is not null and trim(cast(b.raw_department as varchar)) <> '' then 0 else 1 end, case when b.raw_jingli is not null and trim(cast(b.raw_jingli as varchar)) <> '' then 0 else 1 end, case when b.raw_zhuguan is not null and trim(cast(b.raw_zhuguan as varchar)) <> '' then 0 else 1 end, coalesce(cast(b.raw_department as varchar), ''), coalesce(cast(b.raw_jingli as varchar), ''), coalesce(cast(b.raw_zhuguan as varchar), ''), coalesce(cast(b.channel as varchar), ''), coalesce(cast(b.grade as varchar), '') ) end as jingli, case when b.qici is not null and b.lead_id is not null and b.employee_email_name is not null and b.employee_email_prefix is not null then first_value(b.raw_zhuguan) over ( partition by b.qici, b.lead_id, b.employee_email_name, b.employee_email_prefix order by case when coalesce(b.lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.valid_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.conversion_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.order_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.income_amount, 0) <> 0 then 0 else 1 end, case when b.raw_department is not null and trim(cast(b.raw_department as varchar)) <> '' then 0 else 1 end, case when b.raw_jingli is not null and trim(cast(b.raw_jingli as varchar)) <> '' then 0 else 1 end, case when b.raw_zhuguan is not null and trim(cast(b.raw_zhuguan as varchar)) <> '' then 0 else 1 end, coalesce(cast(b.raw_department as varchar), ''), coalesce(cast(b.raw_jingli as varchar), ''), coalesce(cast(b.raw_zhuguan as varchar), ''), coalesce(cast(b.channel as varchar), ''), coalesce(cast(b.grade as varchar), '') ) end as xiaozu, case when b.qici is not null and b.lead_id is not null and b.employee_email_name is not null and b.employee_email_prefix is not null then first_value(b.channel) over ( partition by b.qici, b.lead_id, b.employee_email_name, b.employee_email_prefix order by case when coalesce(b.lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.valid_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.conversion_lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.order_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.income_amount, 0) <> 0 then 0 else 1 end, case when b.raw_department is not null and trim(cast(b.raw_department as varchar)) <> '' then 0 else 1 end, case when b.raw_jingli is not null and trim(cast(b.raw_jingli as varchar)) <> '' then 0 else 1 end, case when b.raw_zhuguan is not null and trim(cast(b.raw_zhuguan as varchar)) <> '' then 0 else 1 end, coalesce(cast(b.raw_department as varchar), ''), coalesce(cast(b.raw_jingli as varchar), ''), coalesce(cast(b.raw_zhuguan as varchar), ''), coalesce(cast(b.channel as varchar), ''), coalesce(cast(b.grade as varchar), '') ) end as org_channel, case when b.qici is not null and b.lead_id is not null and b.employee_email_name is not null and b.employee_email_prefix is not null then first_value(b.grade) over ( partition by b.qici, b.lead_id, b.employee_email_name, b.employee_email_prefix order by case when coalesce(b.lead_count, 0) <> 0 then 0 else 1 end, case when coalesce(b.valid_lead_count, 0) <> 0