st, coalesce(trade_cal.qici, case when substr(f.trade_time, 1, 10) >= '2026-02-25' and substr(f.trade_time, 1, 10) <= '2026-03-02' then '20260227期' when substr(f.trade_time, 1, 10) >= '2026-02-17' and substr(f.trade_time, 1, 10) <= '2026-02-24' then '20260220期' when substr(f.trade_time, 1, 10) >= '2026-02-09' and substr(f.trade_time, 1, 10) <= '2026-02-16' then '20260213期' when substr(f.trade_time, 1, 10) >= '2026-02-03' and substr(f.trade_time, 1, 10) <= '2026-02-08' then '20260206期' when substr(f.trade_time, 1, 10) >= '2026-01-27' and substr(f.trade_time, 1, 10) <= '2026-02-02' then '20260130期' when substr(f.trade_time, 1, 10) >= '2026-01-20' and substr(f.trade_time, 1, 10) <= '2026-01-26' then '20260123期' else date_format(date_trunc('week', cast(f.trade_time as timestamp) - interval '1' day) + interval '4' day, '%Y%m%d') || '期' end) as trade_qici, f.price from finance_dw.app_finance_performance_extend_details_hf f  left join biz_qici_calendar trade_cal on cast(substr(f.trade_time, 1, 10) as date) between trade_cal.start_date and trade_cal.end_date where f.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and f.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'HH')) and f.employee_first_level_department_name = 'H业务线' and f.employee_second_level_department_name = '市场部' and f.employee_third_level_department_name = '市场顾问部' ), period_trade_dd as ( select * from period_trade_dd_raw where trade_qici >= ${qici:1} and trade_qici < ${qici:2} ), period_trade_keys as ( select distinct cast(user_id1 as varchar) as user_id_key, employee_email_name from period_trade_dd ), period_trade_prepared as ( select t.*, row_number() over ( partition by t.id, t.order_number, t.clazz_name, t.user_id1, t.trade_status, t.trade_time, t.trade_type, t.email_prefix, t.employee_email_name, t.grade_list, t.trade_qici order by t.id ) as normal_rn, sum(case when t.trade_type = '正常订单' then t.price end) over ( partition by t.id, t.order_number, t.clazz_name, t.user_id1, t.trade_status, t.trade_time, t.trade_type, t.email_prefix, t.employee_email_name, t.grade_list, t.trade_qici ) as normal_total, row_number() over ( partition by t.employee_email_name, t.user_id1 order by case when t.trade_type = '调课调班' then 0 else 1 end, t.id ) as adjust_rn, round(sum(case when t.trade_type = '调课调班' then t.price end) over ( partition by t.employee_email_name, t.user_id1 ), 3) as adjust_total from period_trade_dd t where t.trade_type in ('正常订单', '调课调班') ), period_trade_union as ( select id, order_number, clazz_name, user_id1, trade_status, trade_time, trade_type, email_prefix, employee_email_name, grade_list, trade_qici, case when trade_type = '正常订单' then normal_total else price end as name_total_price from period_trade_prepared where (trade_type = '正常订单' and normal_rn = 1) or (trade_type = '调课调班' and adjust_rn = 1 and adjust_total != 0) ), period_n_uid as ( select lead_id, original_order_user_number, performance_employee_email_name from ( select x.*, row_number() over ( partition by x.original_order_user_number, x.performance_employee_email_name order by x.qici desc ) as rn from ( select t.lead_id, t.original_order_user_number, t.performance_employee_email_name, coalesce(period_cal.qici, concat( date_format( date_trunc( 'week', date_parse(replace(concat(t.trade_group_period_year, t.trade_group_period_term), '期', ''), '%Y%m%d') - interval '1' day ) + interval '4' day, '%Y%m%d' ), '期' )) as qici from service_dw.dws_crm_order_lead_attribute_income_refund_stats_detail_hf t  inner join period_trade_keys pk on cast(t.original_order_user_number as varchar) = pk.user_id_key and t.performance_employee_email_name = pk.employee_email_name left join biz_qici_calendar period_cal on cast(date_parse(replace(concat(t.trade_group_period_year, t.trade_group_period_term), '期', ''), '%Y%m%d') as date) between period_cal.start_date and period_cal.end_date where t.dt = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'YYYYMMdd')) and t.hour = (FORMAT_DATETIME(CURRENT_TIMESTAMP - INTERVAL '2' HOUR, 'HH')) and t.course_first_level_department_name in ('H业务线', 'A业务线', 'EM业务线', 'LL业务线', 'TT', 'TUTU', 'TT业务线') and t.course_second_level_department_name in ('精品班学部', '菁英班学部', '市场部', '本地化大班学部', '一对一学部', '青橙项目部') and t.performance_first_level_department_name = 'H业务线' and t.performance_second_level_department_name = '市场部' and t.performance_third_level_department_name = '市场顾问部' ) x ) x where rn = 1 ), lead_dim_period as ( select lead_id, employee_email_name, lead_qici, channel, grade, jingli, xiaozu from ( select l.lead_id, l.employee_email_name, l.qici as lead_qici, l.org_channel as channel, l.org_grade as grade, l.jingli, l.xiaozu, row_number() over ( partition by l.lead_id, l.employee_email_name order by l.qici desc, l.org_channel, l.org_grade, l.jingli, l.xiaozu ) as rn from lead_base l ) x where rn = 1 ), period_trade as ( select u.trade_qici as qici, d.channel, d.grade, d.jingli, d.xiaozu, d.employee_email_name, u.name_total_price, case when date_parse(substr(d.lead_qici, 1, 8), '%Y%m%d') = date_parse(substr(u.trade_qici, 1, 8), '%Y%m%d') then 0 when (d.lead_qici = '20260716期' and u.trade_qici = '20260722期') or (d.lead_qici = '20260722期' and u.trade_qici = '20260728期') or (d.lead_qici = '20260728期' and u.trade_qici = '20260803期') or (d.lead_qici = '20260803期' and u.trade_qici = '20260808期') or (d.lead_qici = '20260808期' and u.trade_qici = '20260815期') or (d.lead_qici = '20260815期' and u.trade_qici = '20260821期') then 1 when date_diff( 'day', date_parse(substr(d.lead_qici, 1, 8), '%Y%m%d'), date_parse(substr(u.trade_qici, 1, 8), '%Y%m%d') ) = 7 then 1 when (d.lead_qici = '20260716期' and u.trade_qici = '20260728期') or (d.lead_qici = '20260722期' and u.trade_qici = '20260803期') or (d.lead_qici = '20260728期' and u.trade_qici = '20260808期') or (d.lead_qici = '20260803期' and u.trade_qici = '20260815期') or (d.lead_qici = '20260808期' and u.trade_qici = '20260821期') then 2 when date_diff( 'day', date_parse(substr(d.lead_qici, 1, 8), '%Y%m%d'), date_parse(substr(u.trade_qici, 1, 8), '%Y%m%d') ) between 14 and 21 then 2 when (d.lead_qici = '20260722期' and u.trade_qici = '20260716期') or (d.lead_qici = '20260728期' and u.trade_qici = '20260722期') or (d.lead_qici = '20260803期' and u.trade_qici = '20260728期') or (d.lead_qici = '20260808期' and u.trade_qici = '20260803期') or (d.lead_qici = '20260815期' and u.trade_qici = '20260808期') or (d.lead_qici = '20260821期' and u.trade_qici = '20260815期') then 4 when date_diff( 'day', date_parse(substr(d.lead_qici, 1, 8), '%Y%m%d'), date_parse(substr(u.trade_qici, 1, 8), '%Y%m%d') ) = -7 then 4 else 3 end as week_diff from period_trade_union u left join period_n_uid n on cast(u.user_id1 as varchar) = cast(n.original_order_user_number as varchar) and u.employee_email_name = n.performance_employee_email_name left join lead_dim_period d on n.lead_id = d.lead_id and u.employee_email_name = d.employee_email_name where d.employee_email_name is not null ), period_conv as ( select qici, channel, cast(null as varchar) as rule_name, grade, cast(null as varchar) as depart_1, cast(null as varchar) as department, jingli, xiaozu, employee_email_name, sum(case when week_diff = 0 then name_total_price else 0 end) as period_gmv_7, sum(case when week_diff = 1 then name_total_price else 0 end) as period_gmv_14, sum(case when week_diff = 2 then name_total_price else 0 end) as period_gmv_30, sum(case when week_diff = 3 then name_total_price else 0 end) as period_gmv_n30, sum(case when week_diff = 4 then name_total_price else 0 end) as period_gmv_7_h, sum(name_total_price) as period_gmv_total, sum(case when week_diff = 0 and name_total_price < 0 then name_total_price else 0 end) as period_refund_7, sum(case when week_diff = 1 and name_total_price < 0 then name_total_price else 0 end) as period_refund_14, sum(case when week_diff = 2 and name_total_price < 0 then name_total_price else 0 end) as period_refund_30, sum(case when week_diff = 3 and name_total_price < 0 then name_total_price else 0 end) as period_refund_n30, sum(case when week_diff = 4 and name_total_price < 0 then name_total_price else 0 end) as period_refund_7_p, sum(case when name_total_price < 0 then name_total_price else 0 end) as period_refund_total from period_trade where name_total_price <> 0 group by qici, channel, grade, jingli, xiaozu, employee_email_name ), org_raw as ( select employee_email_name, email_prefix as employee_email_prefix, employee_name, is_on_job, job_status from market_employee_dim where 1 = 1 and ( last_resign_date is null or last_resign_date = '' or cast(last_resign_date as date) >= date '2026-05-01' ) ), period_consultant as ( select qici, channel, grade, jingli, xiaozu, employee_email_name, sum(period_gmv_7) as period_gmv_7, sum(period_gmv_14) as period_gmv_14, sum(period_gmv_30) as period_gmv_30, sum(period_gmv_n30) as period_gmv_n30, sum(period_gmv_7_h) as period_gmv_7_h, sum(period_gmv_total) as period_gmv_total, sum(period_refund_7) as period_refund_7, sum(period_refund_14) as period_refund_14, sum(period_refund_30) as period_refund_30, sum(period_refund_n30) as period_refund_n30, sum(period_refund_7_p) as period_refund_7_p, sum(period_refund_total) as period_refund_total from period_conv group by qici, channel, grade, jingli, xiaozu, employee_email_name ), joined as ( select cm.*, org.employee_name, org.is_on_job, org.job_status, coalesce(pc.period_gmv_7, 0) as period_gmv_7, coalesce(pc.period_gmv_14, 0) as period_gmv_14, coalesce(pc.period_gmv_30, 0) as period_gmv_30, coalesce(pc.period_gmv_n30, 0) as period_gmv_n30, coalesce(pc.period_gmv_7_h, 0) as period_gmv_7_h, coalesce(pc.period_gmv_total, 0) as period_gmv_total, coalesce(pc.period_refund_7, 0) as period_refund_7, coalesce(pc.period_refund_14, 0) as period_refund_14, coalesce(pc.period_refund_30, 0) as period_refund_30, coalesce(pc.period_refund_n30, 0) as period_refund_n30, coalesce(pc.period_refund_7_p, 0) as period_refund_7_p, coalesce(pc.period_refund_total, 0) as period_refund_total, coalesce(multi.multi_lead_count, 0) as multi_lead_count, coalesce(multi.multi_pay_user_head_count, 0) as multi_pay_user_head_count, coalesce(multi.multi_pay_subject_person_count, 0) as multi_pay_subject_person_count, coalesce(multi.multi_net_income, 0) as multi_net_income, coalesce(multi.multi_subject_1_user_count, 0) as multi_subject_1_user_count, coalesce(multi.multi_subject_1_gmv, 0) as multi_subject_1_gmv, coalesce(multi.multi_subject_2_3_user_count, 0) as multi_subject_2_3_user_count, coalesce(multi.multi_subject_2_3_gmv, 0) as multi_subject_2_3_gmv, coalesce(multi.multi_subject_3_plus_user_count, 0) as multi_subject_3_plus_user_count, coalesce(multi.multi_subject_3_plus_gmv, 0) as multi_subject_3_plus_gmv, coalesce(multi.multi_subject_0_user_count, 0) as multi_subject_0_user_count, coalesce(multi.multi_subject_0_gmv, 0) as multi_subject_0_gmv, coalesce(multi.multi_valid_lead_count, 0) as multi_valid_lead_count, coalesce(multi.multi_trade_income, 0) as multi_trade_income, coalesce(multi.multi_net_trade_income, 0) as multi_net_trade_income, coalesce(multi.multi_regular_course_user_count, 0) as multi_regular_course_user_count, coalesce(multi.multi_regular_course_order_count, 0) as multi_regular_course_order_count from consultant_metric cm left join period_consultant pc on cm.qici = pc.qici and cm.channel = pc.channel and cm.grade = pc.grade and cm.jingli = pc.jingli and coalesce(cm.xiaozu, '') = coalesce(pc.xiaozu, '') and coalesce(cm.employee_email_name, '') = coalesce(pc.employee_email_name, '') left join multi on cm.qici = multi.qici and cm.channel = multi.channel and cm.grade = multi.grade and cm.jingli = multi.jingli and coalesce(cm.xiaozu, '') = coalesce(multi.xiaozu, '') and coalesce(cm.employee_email_name, '') = coalesce(multi.employee_email_name, '') and coalesce(cm.employee_email_prefix, '') = coalesce(multi.employee_email_prefix, '') left join org_raw org on cm.employee_email_name = org.employee_email_name ) select * from joined
